# Plugins
## [Use a plugin](https://opencode.ai/docs/plugins/#use-a-plugin)
### [From npm](https://opencode.ai/docs/plugins/#from-npm)
```
{

  "$schema": "https://opencode.ai/config.json",

  "plugin": ["opencode-helicone-session", "opencode-wakatime", "@my-org/custom-plugin"]

}
```

## [Examples](https://opencode.ai/docs/plugins/#examples)
### [Send notifications](https://opencode.ai/docs/plugins/#send-notifications)
```
export const NotificationPlugin = async ({ project, client, $, directory, worktree }) => {

  return {

    event: async ({ event }) => {

      // Send notification on session completion

      if (event.type === "session.idle") {

        await $`osascript -e 'display notification "Session completed!" with title "opencode"'`

      }

    },

  }

}
```

### [Compaction hooks](https://opencode.ai/docs/plugins/#compaction-hooks)
```
import type { Plugin } from "@opencode-ai/plugin"

export const CompactionPlugin: Plugin = async (ctx) => {

  return {

    "experimental.session.compacting": async (input, output) => {

      // Inject additional context into the compaction prompt

      output.context.push(`

## Custom Context

Include any state that should persist across compaction:

- Current task status

- Important decisions made

- Files being actively worked on

`)

    },

  }

}
```

```
import type { Plugin } from "@opencode-ai/plugin"

export const CustomCompactionPlugin: Plugin = async (ctx) => {

  return {

    "experimental.session.compacting": async (input, output) => {

      // Replace the entire compaction prompt

      output.prompt = `

You are generating a continuation prompt for a multi-agent swarm session.

Summarize:

1. The current task and its status

2. Which files are being modified and by whom

3. Any blockers or dependencies between agents

4. The next steps to complete the work

Format as a structured prompt that a new agent can use to resume work.

`

    },

  }

}
```

## Six Ways to Implement Hooks in OpenCode
### 2. SDK with Event Streaming
```
import { createOpencodeClient } from "@opencode-ai/sdk"

const client = createOpencodeClient({
  baseUrl: "http://localhost:4096"
})

// Subscribe to all events
const eventStream = await client.event.subscribe()

for await (const event of eventStream) {
  console.log("📡 Event:", event.type)

  if (event.type === "session.idle") {
    // Session completed - send notification
    await sendSlackMessage("OpenCode session completed!")
  }
}
```

### 4. GitHub Integration
```
name: opencode
on:
  issue_comment:
    types: [created]

jobs:
  opencode:
    if: contains(github.event.comment.body, '/opencode')
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: sst/opencode/github@latest
        env:
          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}
        with:
          model: anthropic/claude-sonnet-4-20250514
```

### 6. Non-Interactive Mode
```
# Run a command and get JSON output
opencode run "analyze code quality" -f json -q

# Continue a previous session
opencode run "implement the fixes" -c session-id

# Use in a pre-commit hook
opencode run "review my changes and ensure no secrets are committed" -q
```

## Practical Use Cases with Code
### Notifications: Slack Integration
```
export const SlackNotifier: Plugin = async () => {
  return {
    event: async ({ event }) => {
      if (event.type === "session.idle") {
        await fetch(process.env.SLACK_WEBHOOK_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            text: `✅ OpenCode session completed!`,
            blocks: [{\
              type: "section",\
              text: {\
                type: "mrkdwn",\
                text: `*Session ID:* ${event.properties.sessionId}\n*Files modified:* ${event.properties.filesModified}`\
              }\
            }]
          })
        })
      }
    }
  }
}
```

# Effect
```
bun add @opencode/client effect
```

## Create a client [#](https://opencode.ai/v2/docs/build/client/effect#create-a-client)
```
import { AbsolutePath, Location, OpenCode } from "@opencode/client/effect"
import { Effect } from "effect"
import { FetchHttpClient } from "effect/http"

const program = Effect.gen(function* () {
  const client = yield* OpenCode.make({ baseUrl: "http://localhost:4096" })
  const session = yield* client.session.create({
    location: Location.Ref.make({ directory: AbsolutePath.make("/workspace") }),
  })
  yield* client.session.prompt({
    sessionID: session.id,
    text: "Review the current changes",
  })
  return session
})

const session = await Effect.runPromise(program.pipe(Effect.provide(FetchHttpClient.layer)))
```

## Headers and requests [#](https://opencode.ai/v2/docs/build/client/effect#headers-and-requests)
```
import { HttpClient, HttpClientRequest } from "effect/http"

const httpClient = yield * HttpClient.HttpClient
const client =
  yield *
  OpenCode.make({ baseUrl: "https://opencode.example.com" }).pipe(
    Effect.provideService(
      HttpClient.HttpClient,
      HttpClient.mapRequest(httpClient, (request) =>
        HttpClientRequest.setHeaders(request, { authorization: `Bearer ${process.env.OPENCODE_TOKEN}` }),
      ),
    ),
  )

const sessions = yield * client.session.list()
```

## Stream events [#](https://opencode.ai/v2/docs/build/client/effect#stream-events)
```
import { Effect, Stream } from "effect"

yield *
  client.event.subscribe().pipe(Stream.runForEach((event) => Effect.logInfo("OpenCode event", { type: event.type })))
```

## Plugin RPC [#](https://opencode.ai/v2/docs/build/client/effect#plugin-rpc)
```
import { Acme } from "opencode-acme-plugin/rpc"

const acme = client.rpc(Acme)
const result = yield * acme.search({ query: "hello" }, { location: { directory: "/workspace" } })

yield *
  acme.events
    .subscribe("updated")
    .pipe(
      Stream.runForEach((event) =>
        Effect.logInfo("Plugin event", { type: event.type, location: event.location, text: event.data.text }),
      ),
    )
```

## Local background service [#](https://opencode.ai/v2/docs/build/client/effect#local-background-service)
```
import { NodeFileSystem } from "@effect/platform-node"
import { OpenCode } from "@opencode/client/effect"
import { Service } from "@opencode/client/effect/service"
import { Effect } from "effect"
import { FetchHttpClient, HttpClient, HttpClientRequest } from "effect/http"

const program = Effect.gen(function* () {
  const endpoint = yield* Service.ensure()
  const httpClient = yield* HttpClient.HttpClient
  const client = yield* OpenCode.make({ baseUrl: endpoint.url }).pipe(
    Effect.provideService(
      HttpClient.HttpClient,
      HttpClient.mapRequest(httpClient, (request) => HttpClientRequest.setHeaders(request, Service.headers(endpoint))),
    ),
  )
  return yield* client.server.info()
})

const health = await Effect.runPromise(
  program.pipe(Effect.provide(FetchHttpClient.layer), Effect.provide(NodeFileSystem.layer)),
)
```
